// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/admin/databases", wrapper.ListDatabaseConnections)
	router.POST(options.BaseURL+"/admin/databases", wrapper.CreateDatabaseConnection)
	router.GET(options.BaseURL+"/admin/databases/:id", wrapper.GetDatabaseConnection)
	router.PATCH(options.BaseURL+"/admin/databases/:id", wrapper.UpdateDatabaseConnection)
	router.GET(options.BaseURL+"/admin/grants", wrapper.ListGrants)
	router.GET(options.BaseURL+"/admin/groups", wrapper.ListGroups)
	router.POST(options.BaseURL+"/admin/groups", wrapper.CreateGroup)
	router.DELETE(options.BaseURL+"/admin/groups/:id", wrapper.DeleteGroup)
	router.GET(options.BaseURL+"/admin/groups/:id", wrapper.GetGroup)
	router.PATCH(options.BaseURL+"/admin/groups/:id", wrapper.UpdateGroup)
	router.DELETE(options.BaseURL+"/admin/groups/:id/grants/:connectionId", wrapper.DeleteGrant)
	router.PUT(options.BaseURL+"/admin/groups/:id/grants/:connectionId", wrapper.SetGrant)
	router.DELETE(options.BaseURL+"/admin/groups/:id/members/:userId", wrapper.RemoveGroupMember)
	router.PUT(options.BaseURL+"/admin/groups/:id/members/:userId", wrapper.AddGroupMember)
	router.GET(options.BaseURL+"/admin/users", wrapper.ListUsers)
	router.POST(options.BaseURL+"/admin/users", wrapper.CreateUser)
	router.GET(options.BaseURL+"/admin/users/:id", wrapper.GetUser)
	router.PATCH(options.BaseURL+"/admin/users/:id", wrapper.UpdateUser)
	router.POST(options.BaseURL+"/admin/users/:id/password", wrapper.ResetUserPassword)
	router.POST(options.BaseURL+"/auth/login", wrapper.Login)
	router.POST(options.BaseURL+"/auth/logout", wrapper.Logout)
	router.POST(options.BaseURL+"/auth/password", wrapper.ChangePassword)
	router.GET(options.BaseURL+"/auth/session", wrapper.GetSession)
	router.GET(options.BaseURL+"/databases/:id/migrations", wrapper.ListMigrations)
	router.POST(options.BaseURL+"/databases/:id/migrations", wrapper.CreateMigration)
	router.PATCH(options.BaseURL+"/databases/:id/migrations/:migrationId", wrapper.UpdateMigration)
	router.GET(options.BaseURL+"/databases/:id/migrations/:migrationId/diff", wrapper.GetMigrationDiff)
	router.POST(options.BaseURL+"/databases/:id/migrations/:migrationId/execute", wrapper.ExecuteMigration)
	router.POST(options.BaseURL+"/databases/:id/query", wrapper.ExecuteDatabaseQuery)
	router.POST(options.BaseURL+"/databases/:id/rows", wrapper.MutateRows)
	router.GET(options.BaseURL+"/databases/:id/schema", wrapper.GetDatabaseSchema)
	router.GET(options.BaseURL+"/databases/:id/table-counts", wrapper.ListTableCounts)
	router.GET(options.BaseURL+"/health", wrapper.GetHealth)
	router.GET(options.BaseURL+"/me/databases", wrapper.ListMyDatabases)
}
